$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5b7417c1bd6f4e8a1181f2e7295a3e28'] = 'Esta opção permite atribuir o grupo como grupo de clientes padrão. O grupo de clientes padrão será configurado em relação ao último endereço adicionado pelo cliente.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ab2004936572b7bcf164741f383f4c97'] = 'Alterar grupo padrão com endereço';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_307181015f28b24b5cf56a56f268fefc'] = 'Esta opção permite alterar o grupo padrão do cliente associado ao país nesta seção quando o cliente seleciona um endereço padrão ou durante o processo de compra. Se o endereço selecionado não tiver um número de IVA válido, o sistema mudará para o grupo padrão do cliente Prestashop';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f008d6b21c614caada820eac4e9ae732'] = 'Remover cliente de outros grupos';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_48cade9acdfa67cc5014f8e885463462'] = 'Esta opção remove o cliente dos grupos onde estava atribuído anteriormente e deixa-o apenas atribuído ao grupo que está configurado por país nesta seção. O grupo padrão será alterado para o grupo atual atribuído.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1ccca8b7e16706b70eb3862d8cac1cf3'] = 'Configurações de ativação';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5c421a5582c9affbd59ce0fbe57a4060'] = 'Os países da UE são selecionados por padrão. A opção [Countries for validation] serve apenas para adicionar ou remover países que pertencem à União Europeia ou têm acordo com operações intracomunitárias. Em uma situação normal, essa opção é predefinida e não deve ser alterada. Leve em consideração que o Norte da Irlanda está incluído para operações intracomunitárias e pertence ao Reino Unido (Inglaterra).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1a7c23373b408af50cb839fbe7d52c85'] = 'Validação de back-office';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_882cb664782409edd93fd5d3ab85efec'] = 'Ative a validação para números de IVA na seção Endereço do Back-office.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_50da52ae50ce1c69d9ec84f9ae7de0e1'] = 'Alguns módulos utilizam controllers pertencentes ao back-office para criação de endereços de clientes através de tarefas cron ou através de processos. Para que o módulo possa validar os números de IVA destes endereços criados, esta opção deve ser ativada.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_bb7bd05d489b31a0c31edfd4897745f4'] = 'Validação de front-office';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9176ffc4cac7d0b19daba445c764c2b1'] = 'Ative a validação para números de IVA na secção Morada do Front-office quando um cliente criar ou modificar uma morada ou durante o processo de pagamento.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_32b4427fd2b69a2c80d21c213e50f974'] = 'Países para validação';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f173aae292b6e3a5365cb4ac449d60b5'] = 'Selecione os países para ativar a validação. Você não deve modificar esta lista, a menos que os regulamentos para operações intracomunitárias mudem e os países envolvidos sejam modificados.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_2d59f051b72e3fab1863a7720267abf8'] = 'CTRL e clique ou clique e arraste para selecionar várias opções.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c9cc8cce247e49bae79f15173ce97354'] = 'Salve ';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b51d6159f43c28990c668ee0f5722e68'] = 'Leve em consideração que para que a operação de isenção fiscal seja legalmente correta, o comerciante, além do cliente, deve estar registrado com IVA intracomunitário válido. O sistema validará o número de IVA intracomunitário do comerciante por VIES ou GOV.UK antes de salvá-lo no banco de dados.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_4c4974ffdbc418a104b9ac8fe50329f2'] = 'IVA do comerciante';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6c5e748d9e2d43bffbcf34fba6bf83c8'] = 'Inserir o NIF do comerciante (com código ISO) com o qual o negócio está registado para operações intracomunitárias. Escreva o número completo com o código ISO (Ex: FR17852960). Números de IVA do Reino Unido não são permitidos.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1709b640f134a404881e88edc01258bc'] = 'Isso é necessário para a opção do sistema de validação bidirecional. Pode deixar em branco se você não usar o sistema de validação bidirecional.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d927b3b03a13bf31b7eb8f6ff92e07ca'] = 'Exibir mensagem de aviso no endereço';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8c0a80538a54ae2b99f5d930b34f65e2'] = 'Apresenta mensagens de aviso na secção morada da conta do cliente quando este não tem um número de IVA válido registado, ou tem de registar um número de IVA (opção de campo obrigatório ativada) ou tem de validar o campo da empresa (opção de validação de empresa ativada).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6bf5595b28f11a3701d3dc6c9d6e449d'] = 'Só funciona em Prestashop 1.7 ou superior';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e119406d93b7385c70d4b607a81bcf32'] = 'Não permitir check-out quando o endereço estiver incompleto';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a2f3bd6da6361f19d81c48c65446422f'] = 'Esta opção não permite ao cliente prosseguir com o processo de compra se a morada selecionada tiver o campo NIF ou nome da empresa que deverá ser validado ou preenchido (Dependendo das opções de validação e configuração do campo de IVA selecionadas). Opção útil para clientes que já possuem endereços cadastrados no banco de dados';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d2afdcacd59b06e5541e4c32b24581b7'] = 'Bloco de preço personalizado';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6607b1376017ff8c5845ae0e911f962b'] = 'Adicione um texto personalizado no bloco de preço do produto (abaixo do preço) e será exibido quando um cliente selecionar um endereço com número de IVA válido e isento de impostos.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1b94355921381017449e017baaa43e5e'] = 'É altamente recomendável utilizar o sistema de validação bidirecional para garantir a integridade jurídica da isenção fiscal nas transações intracomunitárias, verificando tanto o número de contribuinte do comerciante como o do cliente. Para validação bidirecional, é necessário definir o número de IVA do comerciante nas configurações gerais. Se a opção IVA do comerciante estiver vazia, o sistema usará a validação unidirecional em qualquer caso.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8dd10878b69a18f881af0c0e36247cb0'] = 'Sistema de validação';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_24b0f41249450fb2b8d43025022f44a8'] = 'Selecione o sistema de validação do número de IVA. Validação 1-way apenas verifica e valida o número de IVA do cliente, mesmo quando o comerciante não tem um número de IVA válido. A validação 2-way envia informação do NIF do comerciante e NIF do cliente e verifica se ambos já estão registados para efetuar operações intracomunitárias com isenção fiscal.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6c106d4c676d2f70ee14fe9ac8b53a99'] = 'Só funciona com a opção de sistema de validação [Format + API system] selecionada.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_147dc6e7f6af2b9b3bb0cf77bab90e41'] = 'Validação 1 via';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_4792ea7be8342c48e29cf2eeae895962'] = 'Validação 2 vias';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_29dcf8f9e61af7c1f9e4bbd16cf4f2cf'] = 'Modo de validação';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c5a4695fbfd74fcfac2a3d505c66d43b'] = 'Esta opção define o modo de validação do IVA. O modo estrito valida os números de IVA com o formato correto inserido pelo cliente (Ex: FR01609493). O modo inteligente valida os números de IVA mesmo que o formato não seja inserido corretamente pelo cliente (Ex: FR-01609493, FR 01609493, FR01.609.493) e salve como formato válido (Ex: FR01609493)';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_006576df800107db40832e2e0fd44931'] = 'Modo estrito';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_dfea54ef85aa32f8489ae0f672d91c5a'] = 'modo inteligente';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_94b93271d0dfce2b59ba77cc690415a3'] = 'tipo de validação';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_99dd2d580dc5196d7e919645a054c28a'] = 'Esta opção define o tipo de validação do IVA. O modo de validação de formato valida apenas o formato de números de IVA (Ex: FR01609493). A validação de formato + API valida o formato do número de IVA e verifica-o no sistema API VIES ou GOV.UK (recomendado para isenção de IVA).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5718f767fd5edcc521f57c23f4527725'] = 'validação de formato';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_3b19c288b70dc9b277b83cb937d1df74'] = 'Validação do sistema de formato + API';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_54df18253716c9795f66ed2d4255833b'] = 'Validação da empresa';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_93370977d5f528ed94a8f7cf6e7156be'] = 'Se estiver habilitado, o campo nome da empresa será validado junto com as informações obtidas do sistema VIES/GOV.UK referente ao número do IVA. Se o cliente não digitar o nome da empresa exatamente como aparece no banco de dados do sistema VIES/GOV.UK, o endereço não será validado com este número de IVA. Os clientes anteriores registados na base de dados com o nome da empresa ainda não validado mas com IVA válido, serão obrigados a atualizar a informação da morada antes de efetuarem uma compra na loja.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ac50ccc149ebb161e8d8d19c3a6a946f'] = 'Para evitar erros nos formulários de endereço, certifique-se de que o campo \"empresa\" seja exibido no formulário. Se esta opção estiver habilitada, este campo será o obrigatório no formulário de endereço.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_71e56d83a626d8268caf28e8eac3d64a'] = 'Inserir nome da empresa automaticamente';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_52800a2170bf04b8329ec097aa422d63'] = 'Se ativado, quando o cliente registrar um endereço com um número de IVA válido, o sistema inserirá o nome da empresa registrada obtido do sistema VIES ou GOV.UK. Caso o cliente tenha inserido outro nome empresarial no campo empresa, este será substituído pelo nome correto cadastrado no sistema.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_be496e62d1ca3007170567553e8441c0'] = 'Esta opção não é compatível com a opção [Company validation] habilitada.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_de333ce299100de1723bb0d246f8845e'] = 'Permitir IVA duplicado';
