$_MODULE['<{advancedvatmanager}prestashop>information_04bf2603a145f70ce793e34cd15f1e45'] = 'Isto significa que, consoante a opção escolhida, o cliente pagará sempre IVA ou ficará isento de pagamento de IVA independentemente das outras condições que reúna. Caso pretenda que o cliente tenha a isenção de IVA de acordo com as condições normais do módulo, deverá retirá-lo desta lista.';
