$_MODULE['<{advancedvatmanager}prestashop>form_660f83a666580bc14c6e247adf94bb9a'] = 'No caso dos módulos destinados a gerir a página de checkout Prestashop, podem existir incompatibilidades com o nosso módulo, pois estes módulos utilizam os seus próprios controladores para gerir essa secção. Por este motivo, recomendamos apenas utilizar nosso módulo com módulos de checkout que estejam nesta lista de compatibilidade ou integração.';
